 static System.Collections.Generic.IEnumerable<DependencyObject> Descendants(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var child in Descendants(VisualTreeHelper.GetChild(o,i)))yield return child;}
 static int checks,failures;static void Check(string text,bool ok){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+text);if(!ok)failures++;}
 static void Pump(){var frame=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(200)};t.Tick+=(s,e)=>{t.Stop();frame.Continue=false;};t.Start();Dispatcher.PushFrame(frame);}
 static int Ink(Bitmap b){int count=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(Math.Max(b.GetPixel(x,y).R,Math.Max(b.GetPixel(x,y).G,b.GetPixel(x,y).B))>50)count++;return count;}
 static void Shot(SpeechBubble b,string path){Pump();b.UpdateLayout();var r=(FrameworkElement)b.Content;var bitmap=new RenderTargetBitmap((int)b.Width,(int)b.Height,96,96,PixelFormats.Pbgra32);bitmap.Render(r);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
 static T Find<T>(DependencyObject o,Func<T,bool> test)where T:DependencyObject{var item=o as T;if(item!=null&&test(item))return item;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++){var r=Find<T>(VisualTreeHelper.GetChild(o,i),test);if(r!=null)return r;}return null;}
 static T Named<T>(DependencyObject o,string name)where T:DependencyObject{return Find<T>(o,x=>System.Windows.Automation.AutomationProperties.GetName(x)==name);}
 static void Click(Window w,string label){var b=Find<Button>(w,x=>Convert.ToString(x.Content)==label);if(b==null)throw new Exception("Missing button "+label);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var cfg=new MonitorConfig{TaskbarItems=new List<string>{"cpu","memory","download","upload"}};var a=cfg.Appearance;a.FontName="Microsoft YaHei UI";a.AutoTheme=false;a.LabelColor=a.ValueColor=a.GradientEnd="#FFFFFF";a.Transparent=true;a.ShowLabels=true;a.RowGap=0;a.VerticalPadding=0;a.AutoFit=false;var sample=new SystemSample{Cpu=98.5,MemoryTotal=32,MemoryUsed=28,Download=123.45*1048576,Upload=543.2*1024};
 foreach(double dpi in new[]{1.0,1.25,1.5,2.0}){a.FontSize=11;var layout=TaskbarPainter.Geometry(cfg,dpi,100,sample);using(var flat=new Bitmap(layout.Size.Width,layout.Size.Height))using(var gradient=new Bitmap(layout.Size.Width,layout.Size.Height)){using(var g=Graphics.FromImage(flat)){g.Clear(System.Drawing.Color.Transparent);a.GradientText=false;TaskbarPainter.Draw(g,cfg,sample,dpi,layout);}using(var g=Graphics.FromImage(gradient)){g.Clear(System.Drawing.Color.Transparent);a.GradientText=true;TaskbarPainter.Draw(g,cfg,sample,dpi,layout);}Console.WriteLine("Coverage "+dpi+": "+Ink(flat)+" / "+Ink(gradient));flat.Save(Path.Combine(args[0],"flat-"+dpi+".png"));gradient.Save(Path.Combine(args[0],"gradient-"+dpi+".png"));Check("gradient keeps GDI glyph coverage at DPI "+dpi,Ink(gradient)>=Ink(flat)*.95);}}
 a.Item("cpu").GradientStart="#FF3300";a.Item("cpu").GradientEnd="#FFDD00";a.Validate();var json=new System.Web.Script.Serialization.JavaScriptSerializer();var restored=json.Deserialize<TaskbarAppearance>(json.Serialize(a));Check("per item gradient survives serialization",restored.Item("cpu").GradientStart=="#FF3300"&&restored.Item("cpu").GradientEnd=="#FFDD00");using(var b=TaskbarPainter.Preview(cfg,sample)){b.Save(Path.Combine(args[0],"gradient-taskbar.png"));Check("per item gradient renders",Ink(b)>50);}
 foreach(string preference in new[]{"auto","upper","right","left","top","bottom"})foreach(double left in new[]{-1800.0,-250.0}){var p=BubbleLogic.Arrange(left,200,116,168,320,180,-1920,0,0,1080,preference);Check("bubble stays on negative monitor "+preference+left,p.X>=-1912&&p.X+320<=-8&&p.Y>=8&&p.Y+180<=1072);}
 Check("auto can use side",BubbleLogic.Arrange(600,300,116,168,320,180,0,0,1920,1080,"auto").Side=="upper-right");Check("right preference uses right",BubbleLogic.Arrange(600,300,116,168,320,180,0,0,1920,1080,"right").Side=="right");Check("edge flips to left",BubbleLogic.Arrange(1750,300,116,168,320,180,0,0,1920,1080,"right").Side=="left");Check("monitor notifications have correct heading",BubbleLogic.Heading(new BubbleMessage{Key="monitor:cpu",Notification=true})=="系统资源预警");
 var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var bubble=new SpeechBubble();try{foreach(string style in new[]{"paper","blue","kid"}){bubble.Options=new BubbleAppearance{Style=style,Position="auto",FontSize=16,Width=340};bubble.Render(new BubbleMessage{Key="work-end",Notification=true,Text="距离下午下班还有 15 分钟。\n保存正在编辑的内容，准备收尾。"},2,650,400,600,new Rect(0,0,1920,1080));Shot(bubble,Path.Combine(args[0],"bubble-"+style+".png"));Check("native bubble renders "+style,bubble.IsVisible&&bubble.Width==340);}
 var longText=String.Concat(Enumerable.Repeat("这是一段用于验证长消息阅读和段落排版的文本。\n",12));var message=new BubbleMessage{Key="codex:test",Notification=true,Text=longText};bubble.Render(message,0,650,400,600,new Rect(0,0,1920,1080));Pump();var button=(Button)typeof(SpeechBubble).GetField("expand",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(bubble);Check("long message offers expansion",button.Visibility==Visibility.Visible);button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));bubble.Render(message,0,650,400,600,new Rect(0,0,1920,1080));var body=(TextBlock)typeof(SpeechBubble).GetField("body",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(bubble);Check("expanded message retains full content",body.Text==longText.Trim());Shot(bubble,Path.Combine(args[0],"bubble-expanded.png"));bubble.Hide();var pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);try{pet.Show();Pump();var assistant=(AssistantRuntime)typeof(ConanPet).GetField("assistant",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet);assistant.Config.Monitor.Quota.Enabled=false;typeof(ConanPet).GetMethod("OpenTerminal",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(pet,null);var terminal=(TerminalWindow)typeof(ConanPet).GetField("terminal",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet);terminal.ShowPage("任务栏外观");Pump();Click(terminal,"配色与文字");var scope=Named<System.Windows.Controls.Primitives.ToggleButton>(terminal,"配色范围-cpu");scope.IsChecked=true;scope.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Named<TextBox>(terminal,"配色颜色点颜色").Text="#FF3300";var bar=Named<UsageRampBar>(terminal,"可编辑配色条");bar.SelectPoint(100);Named<TextBox>(terminal,"配色颜色点颜色").Text="#33CCEE";Check("per item gradient is draft",!assistant.Config.Monitor.Appearance.Item("cpu").LabelRamp.Enabled);Click(terminal,"应用并保存任务栏外观");Check("per item gradient applies",assistant.Config.Monitor.Appearance.Item("cpu").LabelRamp.Stops[0].Color=="#FF3300");terminal.ShowPage("气泡外观");Pump();Named<ComboBox>(terminal,"气泡款式").SelectedIndex=1;Named<ComboBox>(terminal,"优先显示位置").SelectedIndex=3;Click(terminal,"保存气泡设置");var runtime=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check("bubble choices survive reload",runtime.Config.BubbleAppearance.Style=="blue"&&runtime.Config.BubbleAppearance.Position=="left");Check("gradient endpoints survive runtime reload",runtime.Config.Monitor.Appearance.Item("cpu").LabelRamp.Stops.Last().Color=="#33CCEE");runtime.Telemetry.Dispose();}finally{pet.Close();}}finally{bubble.Close();app.Shutdown();}
 File.WriteAllText(Path.Combine(args[0],"bubble-gradient-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");return failures==0?0:1;
 }
